import Foundation

@MainActor
final class ChatViewModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isSending = false
    @Published private(set) var connectionStatus: ConnectionStatus = .disconnected
    @Published private(set) var providerInfo: String?
    @Published var inputText = ""
    @Published private(set) var ownerToken: String?
    @Published private(set) var isAuthenticated = false
    @Published private(set) var authError: String?
    @Published private(set) var healthSHA: String?

    enum ConnectionStatus {
        case disconnected
        case authenticating
        case connected
        case error(String)
    }

    private let apiService: IVXAPIService

    init(apiService: IVXAPIService = IVXAPIService()) {
        self.apiService = apiService
    }

    func authenticate() async {
        connectionStatus = .authenticating
        authError = nil

        do {
            let token = try await apiService.ownerLogin(
                email: IVXConstants.ownerEmail,
                emergency: IVXConstants.emergencyCode
            )
            self.ownerToken = token
            self.isAuthenticated = true
            self.connectionStatus = .connected

            await checkHealth()
            await loadWelcomeMessage()
        } catch {
            self.connectionStatus = .error(error.localizedDescription)
            self.authError = error.localizedDescription
        }
    }

    func checkHealth() async {
        do {
            let health = try await apiService.checkHealth()
            self.healthSHA = String(health.commit.prefix(12))
        } catch {
            self.healthSHA = "unknown"
        }
    }

    private func loadWelcomeMessage() async {
        let welcome = ChatMessage(
            role: .assistant,
            content: "IVX IA online. I'm your autonomous engineering assistant — I can inspect code, run tests, query your Supabase database, and deploy fixes to GitHub. What do you need?",
            provider: "ivx_direct_answer"
        )
        messages.append(welcome)
    }

    func send() async {
        let text = inputText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty, !isSending, isAuthenticated else { return }

        inputText = ""

        let userMessage = ChatMessage(role: .user, content: text)
        messages.append(userMessage)

        let placeholderId = UUID().uuidString
        let placeholder = ChatMessage(
            id: placeholderId,
            role: .assistant,
            content: "",
            isStreaming: true
        )
        messages.append(placeholder)

        isSending = true

        do {
            let response = try await apiService.sendChatMessage(
                message: text,
                token: ownerToken ?? ""
            )

            if let index = messages.firstIndex(where: { $0.id == placeholderId }) {
                messages[index] = ChatMessage(
                    id: placeholderId,
                    role: .assistant,
                    content: response.answer ?? "No response received.",
                    provider: response.provider ?? response.source,
                    isStreaming: false
                )
            }
            providerInfo = response.provider ?? response.source
        } catch {
            if let index = messages.firstIndex(where: { $0.id == placeholderId }) {
                messages[index] = ChatMessage(
                    id: placeholderId,
                    role: .assistant,
                    content: "Error: \(error.localizedDescription)",
                    isStreaming: false
                )
            }
        }

        isSending = false
    }

    func clearConversation() {
        messages.removeAll()
        Task { await loadWelcomeMessage() }
    }
}

